+// Shortcuts that make work look done, found in what the run changed. A finding names a line cedia can point at,
+// so the reminder, the receipt and the evidence all say the same thing. Heuristic: it reads added lines only.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; line?: string };
+
+const CODE = /\.(c|cc|cpp|go|java|js|jsx|kt|mjs|cjs|py|rb|rs|swift|ts|tsx)$/;
+const TEST = /(\.test\.|\.spec\.|_test\.|(^|\/)tests?\/|(^|\/)test_[^/]*$)/;
+const SKIP = /\b(it|test|describe)\.skip\(|\b[xf](it|describe|test)\(|\bt\.Skip(Now|f)?\(|@pytest\.mark\.skip|\bpytest\.skip\(/;
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', /@ts-(ignore|nocheck|expect-error)|eslint-disable|#\s*type:\s*ignore|#\s*noqa\b|#\s*pylint:\s*disable|\/\/\s*nolint/],
+  ['swallowed-error', /catch\s*(\([^)]*\))?\s*\{\s*\}|\.catch\(\s*\(\s*\)\s*=>\s*\{\s*\}\s*\)|^\s*except\b[^:]*:\s*pass\s*$/],
+  ['type-escape', /\bas any\b|:\s*any\b|<any>/],
+  ['stub', /not[ _-]?implemented|\btodo!\(|\bunimplemented!\(/i],
+];
+
+const assertions = (lines: string[]) => lines.filter((l) => /\b(assert|expect)\b/.test(l)).length;
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    const test = TEST.test(c.path);
+    if (c.deleted) {
+      if (test) out.push({ rule: 'test-deleted', path: c.path });
+      continue;
+    }
+    if (test && assertions(c.removed) > assertions(c.added)) out.push({ rule: 'test-weakened', path: c.path });
+    if (!CODE.test(c.path)) continue;
+    for (const line of c.added) {
+      const rule = test && SKIP.test(line) ? 'test-skipped' : LINE_RULES.find(([, re]) => re.test(line))?.[0];
+      if (rule) out.push({ rule, path: c.path, line: line.trim() });
+    }
+  }
+  return out;
+}
+
+export const flagOf = (f: Finding) => (f.line !== undefined ? `${f.rule} ${f.path}: ${f.line}` : `${f.rule} ${f.path}`);
+
+// Reads a `git diff -U0` (or diff-tree -p -U0) patch. Header lines before a hunk are not content.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/.* b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[1]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+    } else if (!cur) continue;
+    else if (line.startsWith('deleted file mode')) cur.deleted = true;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (inHunk && line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (inHunk && line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
