diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/pricing-rules.test.ts b/test/pricing-rules.test.ts
--- a/test/pricing-rules.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/pricing-rules.test.ts	2026-10-23 20:56:51.559248323 +0000
@@ -0,0 +1,41 @@
+import { expect, test } from 'bun:test';
+import { bulkDiscount } from '../src/pricing/discounts/bulk.ts';
+import { region } from '../src/pricing/regions.ts';
+import { shippingFor } from '../src/pricing/shipping.ts';
+import { totals } from '../src/order/total.ts';
+import type { Cart } from '../src/cart/cart.ts';
+
+test('bulk tiers start at 10 and 50 units', () => {
+  expect(bulkDiscount(9, 10000)).toBe(0);
+  expect(bulkDiscount(10, 10000)).toBe(500);
+  expect(bulkDiscount(49, 10000)).toBe(500);
+  expect(bulkDiscount(50, 10000)).toBe(1000);
+});
+
+test('UK free shipping starts at 4000', () => {
+  expect(region('UK').freeShippingFrom).toBe(4000);
+  expect(shippingFor(region('UK'), 3999)).toBe(700);
+  expect(shippingFor(region('UK'), 4000)).toBe(0);
+});
+
+test('shipping uses the discounted subtotal after the coupon', () => {
+  // 5000 subtotal, FLAT5 takes 500 -> 4500 < 5000 threshold, so shipping is charged
+  const c: Cart = { region: 'US', coupon: 'FLAT5', lines: [{ sku: 'A', quantity: 1, unitPrice: 5000 }] };
+  const t = totals(c);
+  expect(t.shipping).toBe(800);
+  expect(t.tax).toBe(371); // (4500 + 800) * 7%
+  expect(t.total).toBe(4500 + 800 + t.tax);
+});
+
+test('lines of the same sku are merged before bulk pricing', () => {
+  const c: Cart = {
+    region: 'US',
+    lines: [
+      { sku: 'A', quantity: 6, unitPrice: 1000 },
+      { sku: 'A', quantity: 4, unitPrice: 1000 },
+    ],
+  };
+  const t = totals(c);
+  expect(t.lines.length).toBe(1);
+  expect(t.subtotal).toBe(9500); // 10 units at 1000 with 5% off
+});

