diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/lru.rules.test.ts b/test/lru.rules.test.ts
--- a/test/lru.rules.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/lru.rules.test.ts	2026-10-23 20:57:35.931829703 +0000
@@ -0,0 +1,59 @@
+import { expect, test } from 'bun:test';
+import { LRU, type EvictReason } from '../src/lru.ts';
+
+function setup(capacity: number, ttl: number) {
+  let t = 0;
+  const cache = new LRU<string, number>(capacity, ttl, () => t);
+  const log: [string, number, EvictReason][] = [];
+  cache.onEvict = (k, v, r) => log.push([k, v, r]);
+  return { cache, log, tick: (to: number) => (t = to) };
+}
+
+test('get refreshes recency and expiry edge is exclusive', () => {
+  const { cache, log, tick } = setup(2, 100);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.get('a')).toBe(1);
+  expect(cache.keys()).toEqual(['a', 'b']);
+  cache.set('c', 3);
+  expect(log).toEqual([['b', 2, 'capacity']]);
+  tick(99);
+  expect(cache.get('a')).toBe(1);
+  tick(100);
+  expect(cache.get('c')).toBeUndefined();
+  expect(log.at(-1)).toEqual(['c', 3, 'expired']);
+});
+
+test('set evicts expired entries before live ones', () => {
+  const { cache, log, tick } = setup(2, 10);
+  cache.set('a', 1);
+  tick(5);
+  cache.set('b', 2);
+  tick(10);
+  cache.set('c', 3);
+  expect(log).toEqual([['a', 1, 'expired']]);
+  expect(cache.keys()).toEqual(['c', 'b']);
+  expect(cache.size).toBe(2);
+});
+
+test('delete reasons and return values', () => {
+  const { cache, log, tick } = setup(3, 10);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.delete('a')).toBe(true);
+  tick(10);
+  expect(cache.delete('b')).toBe(false);
+  expect(cache.delete('zz')).toBe(false);
+  expect(log).toEqual([
+    ['a', 1, 'delete'],
+    ['b', 2, 'expired'],
+  ]);
+});
+
+test('set on existing key does not evict it', () => {
+  const { cache, log } = setup(1, 100);
+  cache.set('a', 1);
+  cache.set('a', 2);
+  expect(log).toEqual([]);
+  expect(cache.get('a')).toBe(2);
+});
